SELECT id, name, mis FROM students;

-- Step 6: Create match_face RPC function
CREATE OR REPLACE FUNCTION match_face (query_embedding vector(1404), match_threshold float)
RETURNS TABLE (
    id integer,
    name varchar,
    mis varchar,
    dist float
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT
        students.id,
        students.name,
        students.mis,
        (students.face_encoding <-> query_embedding) AS dist
    FROM students
    WHERE (students.face_encoding <-> query_embedding) <= match_threshold
    ORDER BY dist ASC
    LIMIT 1;
END;
$$;